import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom'; // Assuming react-router-dom

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setError(''); // Clear previous errors

    // Basic validation
    if (!email || !password) {
      setError('Please enter both email and password.');
      return;
    }

    try {
      // * Replace with your actual API call for login *
      console.log('Attempting login with:', { email, password });
      // Example: const response = await fetch('/api/login', { /* ... */ });
      // const data = await response.json();

      // Simulate successful login
      const success = true; // Replace with actual API response check
      if (success) {
        // Store token/user info (e.g., in localStorage or context)
        console.log('Login successful!');
        navigate('/student/dashboard'); // Redirect to student dashboard or appropriate route
      } else {
        // Handle specific API errors
        setError('Invalid credentials. Please try again.');
      }
    } catch (err) {
      console.error('Login error:', err);
      setError('An error occurred during login. Please try again later.');
    }
  };

  return (
    <div className="login-container">
      <h2>Login</h2>
      <form onSubmit={handleLogin}>
        {error && <p className="error-message" style={{ color: 'red' }}>{error}</p>}
        <div>
          <label htmlFor="email">Email:</label>
          <input
            type="email"
            id="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
        </div>
        <div>
          <label htmlFor="password">Password:</label>
          <input
            type="password"
            id="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
        </div>
        <button type="submit">Login</button>
      </form>
      <p>
        Don't have an account? <Link to="/register">Register here</Link>
      </p>
      <p>
        <Link to="/forgot-password">Forgot Password?</Link> {/* Optional */}
      </p>
    </div>
  );
}

export default Login;
